def _norm_id(v: str) -> str:
    """يوحّد الأرقام العربية لإنجليزية ويشيل المسافات."""
    v = (v or "").strip().replace(" ", "")
    return v.translate(str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789"))


